//! Array descriptors and bit arrays.
//!
//! An array descriptor generated by the compiler is a `ptrszint` vector:
//! `[0]` data pointer, `[1]` flags/element size, `[2]` bit 0 = allocated, then
//! four entries per dimension starting at index 4 (`lbound`, element count,
//! multiplier, unused), with the *last* dimension first. `REDIM`, `ERASE` and
//! bounds checks on indexing are emitted inline by the compiler; the runtime
//! provides `LBOUND`/`UBOUND` and access to `_BIT` arrays.
//!
//! Replaces `func_lbound`, `func_ubound`, `getubits`, `getbits`, `setbits`.

/// Which bound to read.
#[derive(Clone, Copy, PartialEq, Eq, Debug)]
pub enum Bound {
    Lower,
    Upper,
}

/// `func_lbound` / `func_ubound` on a descriptor. `Err(9)` ("Subscript out
/// of range") for a bad dimension or an unallocated array.
pub fn bound(desc: &[isize], index: i32, num_indexes: i32, which: Bound) -> Result<isize, i32> {
    if index < 1 || index > num_indexes || desc[2] & 1 == 0 {
        return Err(9);
    }
    let i = 4 * (num_indexes - index + 1) as usize;
    Ok(match which {
        Bound::Lower => desc[i],
        Bound::Upper => desc[i].wrapping_add(desc[i + 1]).wrapping_sub(1),
    })
}

fn mask(bsize: u32) -> i64 {
    // ~(-(1<<bsize)), with the x86 shift count masked to 6 bits like the C code.
    !(1i64.wrapping_shl(bsize).wrapping_neg())
}

/// # Safety
/// `base + (i*bsize)>>3` must be readable for 8 bytes.
unsafe fn word(base: *const u8, bit: isize) -> u64 {
    unsafe { base.offset(bit >> 3).cast::<u64>().read_unaligned() }
}

/// `getubits`: element `i` of an unsigned `_BIT * bsize` array.
///
/// # Safety
/// See [`word`]: the legacy code always reads 8 bytes.
pub unsafe fn getubits(bsize: u32, base: *const u8, i: isize) -> u64 {
    let bit = i.wrapping_mul(bsize as isize);
    (unsafe { word(base, bit) } >> (bit & 7)) & mask(bsize) as u64
}

/// `getbits`: element `i` of a signed `_BIT * bsize` array.
///
/// # Safety
/// As [`getubits`].
pub unsafe fn getbits(bsize: u32, base: *const u8, i: isize) -> i64 {
    let m = mask(bsize);
    let bit = i.wrapping_mul(bsize as isize);
    let v = ((unsafe { word(base, bit) } >> (bit & 7)) as i64) & m;
    if v & 1i64.wrapping_shl(bsize.wrapping_sub(1)) != 0 {
        v | !m
    } else {
        v
    }
}

/// `setbits`: stores element `i` of a `_BIT * bsize` array.
///
/// # Safety
/// `base + (i*bsize)>>3` readable and writable for 8 bytes.
pub unsafe fn setbits(bsize: u32, base: *mut u8, i: isize, val: i64) {
    let m = 1u64.wrapping_shl(bsize).wrapping_sub(1);
    let bit = i.wrapping_mul(bsize as isize);
    let sh = (bit & 7) as u32;
    unsafe {
        let p = base.offset(bit >> 3).cast::<u64>();
        let w = p.read_unaligned();
        p.write_unaligned((w & ((m << sh) ^ u64::MAX)) | (((val as u64) & m) << sh));
    }
}

/// Entries in a descriptor with `num_indexes` dimensions: 4 header entries
/// plus 4 per dimension.
fn desc_len(num_indexes: i32) -> usize {
    4 + 4 * num_indexes as usize
}

// ---------------------------------------------------------------- C ABI

/// `func_lbound` (`upper` = 0) / `func_ubound` (`upper` = 1). Returns the
/// BASIC error (0 = success, value in `*out`).
///
/// # Safety
/// `desc` is a descriptor with at least `4*num_indexes+4` entries when
/// `index` is in range.
#[unsafe(no_mangle)]
pub unsafe extern "C" fn qb_array_bound(desc: *const isize, index: i32, num_indexes: i32, upper: i32, out: *mut isize) -> i32 {
    let len = if index >= 1 && index <= num_indexes { desc_len(num_indexes) } else { 3 };
    let d = unsafe { core::slice::from_raw_parts(desc, len) };
    match bound(d, index, num_indexes, if upper != 0 { Bound::Upper } else { Bound::Lower }) {
        Ok(v) => {
            unsafe { *out = v };
            0
        }
        Err(e) => e,
    }
}

/// `getubits`.
///
/// # Safety
/// See [`getubits`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn qb_getubits(bsize: u32, base: *const u8, i: isize) -> u64 {
    unsafe { getubits(bsize, base, i) }
}

/// `getbits`.
///
/// # Safety
/// See [`getbits`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn qb_getbits(bsize: u32, base: *const u8, i: isize) -> i64 {
    unsafe { getbits(bsize, base, i) }
}

/// `setbits`.
///
/// # Safety
/// See [`setbits`].
#[unsafe(no_mangle)]
pub unsafe extern "C" fn qb_setbits(bsize: u32, base: *mut u8, i: isize, val: i64) {
    unsafe { setbits(bsize, base, i, val) }
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn bounds_of_two_dimensional_array() {
        // DIM a(1 TO 3, -2 TO 5): last dimension first.
        let desc = [0, 0, 1, 0, -2, 8, 1, 0, 1, 3, 8, 0];
        assert_eq!(bound(&desc, 1, 2, Bound::Lower), Ok(1));
        assert_eq!(bound(&desc, 1, 2, Bound::Upper), Ok(3));
        assert_eq!(bound(&desc, 2, 2, Bound::Lower), Ok(-2));
        assert_eq!(bound(&desc, 2, 2, Bound::Upper), Ok(5));
        assert_eq!(bound(&desc, 3, 2, Bound::Upper), Err(9));
        assert_eq!(bound(&desc, 0, 2, Bound::Lower), Err(9));
        let erased = [0, 0, 0, 0, 0, 0, 0, 0];
        assert_eq!(bound(&erased, 1, 1, Bound::Lower), Err(9));
    }

    #[test]
    fn c_bound_reads_only_the_descriptor() {
        // exactly 4*n+4 entries: the C entry point must not view more (UB under Miri before)
        let desc: [isize; 12] = [0, 0, 1, 0, -2, 8, 1, 0, 1, 3, 8, 0];
        assert_eq!(desc_len(2), desc.len());
        assert_eq!(desc_len(1), 8);
        let mut out = 0isize;
        // SAFETY: `desc` holds a full 2-dimensional descriptor.
        assert_eq!(unsafe { qb_array_bound(desc.as_ptr(), 1, 2, 1, &mut out) }, 0);
        assert_eq!(out, 3);
        // SAFETY: as above.
        assert_eq!(unsafe { qb_array_bound(desc.as_ptr(), 2, 2, 0, &mut out) }, 0);
        assert_eq!(out, -2);
    }

    #[test]
    fn bit_arrays_round_trip() {
        let mut buf = [0u8; 32];
        unsafe {
            for i in 0..20 {
                setbits(5, buf.as_mut_ptr(), i, i as i64 - 10);
            }
            for i in 0..20 {
                assert_eq!(getbits(5, buf.as_ptr(), i), ((i as i64 - 10) << 59) >> 59);
                assert_eq!(getubits(5, buf.as_ptr(), i), (i as u64).wrapping_sub(10) & 31);
            }
            setbits(1, buf.as_mut_ptr(), 3, -1);
            assert_eq!(getbits(1, buf.as_ptr(), 3), -1);
            assert_eq!(getubits(1, buf.as_ptr(), 3), 1);
        }
    }
}
